/*
 * verify.c - sequential SRE challenge verifier.
 *
 * Design notes
 * ------------
 * This binary is installed setuid root inside the container. All of its input
 * (manifest, stage text, checks.tsv, flag hashes) is generated by the trainer
 * generator as root and is therefore trusted; the *only* untrusted data it
 * handles is argv (check ids, answers, flags), and that is bounds-checked and
 * charset-restricted before use.
 *
 * Because the state directory and the generated inputs are root-only, nearly
 * every operation needs root. We keep euid 0 for the whole run, but we
 * temporarily drop to the invoking (trainee) uid while we touch hostile argv
 * data, so that a latent string-handling bug cannot be leveraged against
 * root-only paths. See priv_enter_user()/priv_leave_user().
 *
 * State layout (all under SRE_STATE_ROOT, default /var/lib/sre-trainer):
 *   manifest                 SEED / STAGES / STAGE lines
 *   stages/NN/instruction    multi-line text
 *   stages/NN/hint           multi-line text
 *   stages/NN/checks.tsv     blank-line-separated key=value blocks
 *   stages/NN/flag.sha256    sha256 hex of the stage flag
 *   final.sha256             sha256 hex of the final flag
 *   state/progress           1-based current stage index
 *   state/clock              epoch seconds at first `next`
 *   state/stage_NN.frag      one fragment per successful check (append order)
 *   state/stage_NN.done      one check id per successful check (append order)
 *   state/records.jsonl      one JSON object per finished run
 *
 * Flag computation: FLAG{ sha256(join(fragments,"|"))[:12] }.
 * Fragments are joined in checks.tsv order (the order a generator can compute
 * ahead of time); if the stored flag.sha256 matches the completion-order join
 * instead, that candidate is used. This keeps the verifier correct whatever
 * order the trainee solves the checks in.
 */
#define _GNU_SOURCE

#include <ctype.h>
#include <errno.h>
#include <limits.h>
#include <stdarg.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <strings.h>
#include <time.h>
#include <unistd.h>
#include <sys/stat.h>
#include <sys/types.h>

#include "sha256.h"
#include "util.h"

#define DEFAULT_ROOT   "/var/lib/sre-trainer"
#define MAX_STAGES     200
#define MAX_CHECKS     32
#define ID_MAX         64
#define FRAG_MAX       200
#define HINT_MAX       400
#define TXT_CAP        (64 * 1024)
#define CHECKS_CAP     (256 * 1024)
#define MANIFEST_CAP   (16 * 1024)
#define DONE_CAP       (16 * 1024)
#define FRAG_CAP       (32 * 1024)
#define JOIN_CAP       (MAX_CHECKS * (FRAG_MAX + 1) + 1)

static char g_root[PATH_MAX];

struct stage_ent {
    char id[ID_MAX];
};

static struct stage_ent g_stage[MAX_STAGES];
static int g_nstage;
static long g_seed;

enum check_type { CT_NONE = 0, CT_HASH, CT_FILE };

struct check_ent {
    char id[ID_MAX];
    enum check_type type;
    char answer[65];        /* type=hash: sha256 of the expected answer */
    char path[PATH_MAX];    /* type=file: absolute path to inspect */
    char sha[65];           /* type=file: expected sha256 of that file */
    char fragment[FRAG_MAX];
    char hint[HINT_MAX];
};

static struct check_ent g_chk[MAX_CHECKS];
static int g_nchk;

/* Scratch buffers kept off the stack; the binary is static and single-threaded. */
static char g_text[TXT_CAP];
static char g_checks_buf[CHECKS_CAP];
static char g_aux[DONE_CAP];

/* ------------------------------------------------------------------ */
/* small helpers                                                       */
/* ------------------------------------------------------------------ */

static int fail(const char *fmt, ...)
{
    va_list ap;

    fputs("verify: ", stderr);
    va_start(ap, fmt);
    vfprintf(stderr, fmt, ap);
    va_end(ap);
    fputc('\n', stderr);
    return 1;
}

/* printf into a bounded buffer; returns nonzero if it did not fit. */
static int spath(char *out, size_t cap, const char *fmt, ...)
{
    va_list ap;
    int r;

    va_start(ap, fmt);
    r = vsnprintf(out, cap, fmt, ap);
    va_end(ap);
    if (r < 0 || (size_t)r >= cap)
        return -1;
    return 0;
}

static int path_stage(char *out, size_t cap, int n, const char *leaf)
{
    return spath(out, cap, "%s/stages/%02d/%s", g_root, n, leaf);
}

static int path_state(char *out, size_t cap, const char *leaf)
{
    return spath(out, cap, "%s/state/%s", g_root, leaf);
}

static int path_state_stage(char *out, size_t cap, int n, const char *ext)
{
    return spath(out, cap, "%s/state/stage_%02d.%s", g_root, n, ext);
}

/* Human-readable form of a read_file_bounded() failure, so a truncated or
 * oversized generated file is reported as such rather than as "missing". */
static const char *read_err(int rc)
{
    switch (rc) {
    case -1:
        return "cannot be opened";
    case -2:
        return "is larger than the supported maximum";
    case -3:
        return "could not be read";
    default:
        return "failed to load";
    }
}

/* Print a text file's contents, guaranteeing a trailing newline. */
static void print_text(const char *text)
{
    size_t len = strlen(text);

    fputs(text, stdout);
    if (len == 0 || text[len - 1] != '\n')
        fputc('\n', stdout);
}

static void fmt_elapsed(long secs, char *out, size_t cap)
{
    long h, m, s;

    if (secs < 0)
        secs = 0;
    h = secs / 3600;
    m = (secs % 3600) / 60;
    s = secs % 60;
    if (h > 0)
        snprintf(out, cap, "%ldh %02ldm %02lds", h, m, s);
    else if (m > 0)
        snprintf(out, cap, "%ldm %02lds", m, s);
    else
        snprintf(out, cap, "%lds", s);
}

/* Count non-empty lines in an in-memory list. */
static int count_lines(const char *buf)
{
    int n = 0;
    const char *p = buf;

    while (*p) {
        const char *nl = strchr(p, '\n');
        size_t len = nl ? (size_t)(nl - p) : strlen(p);
        if (len > 0)
            n++;
        if (!nl)
            break;
        p = nl + 1;
    }
    return n;
}

/* 1 if `needle` is exactly one line of `buf`. */
static int list_has(const char *buf, const char *needle)
{
    const char *p = buf;

    while (*p) {
        const char *nl = strchr(p, '\n');
        size_t len = nl ? (size_t)(nl - p) : strlen(p);
        if (len == strlen(needle) && memcmp(p, needle, len) == 0)
            return 1;
        if (!nl)
            break;
        p = nl + 1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* privilege handling                                                  */
/* ------------------------------------------------------------------ */

/*
 * Captured once in main(), before any seteuid() round trip. Evaluating
 * geteuid() lazily is a trap: after priv_enter_user() the effective uid is the
 * trainee's, so a late check would conclude "not setuid root" and skip the
 * restore, leaving us unprivileged for the root-only state writes.
 */
static int g_setuid_root;

/* Drop euid to the invoking (trainee) uid while handling untrusted argv data. */
static int priv_enter_user(void)
{
    if (!g_setuid_root)
        return 0;
    if (seteuid(getuid()) != 0)
        return -1;
    return 0;
}

/* Restore euid 0 so we can read root-only inputs and write root-only state. */
static int priv_leave_user(void)
{
    if (!g_setuid_root)
        return 0;
    if (seteuid(0) != 0)
        return -1;
    if (geteuid() != 0)
        return -1; /* never continue with less privilege than we need */
    return 0;
}

/* ------------------------------------------------------------------ */
/* root / state plumbing                                               */
/* ------------------------------------------------------------------ */

static int init_root(void)
{
    const char *env = getenv("SRE_STATE_ROOT");
    size_t len;

    /*
     * SRE_STATE_ROOT exists only so the verifier can be exercised against a
     * throwaway tree. It is honoured *only* when we are not setuid root:
     * otherwise a trainee could point the root-privileged binary at a tree they
     * control and use the manifest's file checks as a root-powered oracle.
     */
    if (g_setuid_root && env != NULL && env[0] != '\0') {
        fprintf(stderr, "verify: ignoring SRE_STATE_ROOT (setuid-root installs "
                        "always use %s)\n", DEFAULT_ROOT);
        env = NULL;
    }

    if (env != NULL && env[0] != '\0')
        snprintf(g_root, sizeof(g_root), "%s", env);
    else
        snprintf(g_root, sizeof(g_root), "%s", DEFAULT_ROOT);

    /* strip trailing slashes so path joins stay clean */
    len = strlen(g_root);
    while (len > 1 && g_root[len - 1] == '/')
        g_root[--len] = '\0';

    if (strcmp(g_root, DEFAULT_ROOT) != 0) {
        /* Testing / staging mode: an operator pointed us at an alternate tree,
         * so root is not required and this is not the production data dir. */
        return 0;
    }
    if (geteuid() != 0)
        return fail("must be installed setuid root (or set SRE_STATE_ROOT for testing)");
    return 0;
}

static int ensure_state_dir(void)
{
    char p[PATH_MAX];

    if (mkdir_p(g_root, 0755) != 0)
        return fail("cannot create %s: %s", g_root, strerror(errno));
    if (path_state(p, sizeof(p), "") != 0)
        return fail("path too long");
    if (mkdir_p(p, 0700) != 0)
        return fail("cannot create state dir: %s", strerror(errno));
    return 0;
}

/*
 * Read state/progress. Returns 1..N, or -1 if the file is missing/empty.
 * On malformed content it prints an error and returns 0.
 */
static int read_progress(void)
{
    char p[PATH_MAX];
    char *end;
    long v;

    if (path_state(p, sizeof(p), "progress") != 0)
        return 0;
    if (read_file_bounded(p, g_aux, sizeof(g_aux), NULL) != 0)
        return -1; /* missing => stage 1 */

    trim_ws(g_aux);
    if (g_aux[0] == '\0')
        return -1;
    errno = 0;
    v = strtol(g_aux, &end, 10);
    if (errno != 0 || end == g_aux || *end != '\0' || v < 1 || v > MAX_STAGES) {
        fail("state/progress is corrupt");
        return 0;
    }
    return (int)v;
}

static int write_progress(int n)
{
    char p[PATH_MAX];
    char buf[32];
    int len;

    if (path_state(p, sizeof(p), "progress") != 0)
        return fail("path too long");
    len = snprintf(buf, sizeof(buf), "%d\n", n);
    if (len < 0 || (size_t)len >= sizeof(buf))
        return fail("cannot format progress");
    if (write_file(p, buf, (size_t)len) != 0)
        return fail("cannot write state/progress: %s", strerror(errno));
    return 0;
}

/* Current stage, or 0 after printing an error. */
static int current_stage(void)
{
    int v = read_progress();
    return v < 0 ? 1 : v;
}

static int ensure_clock(void)
{
    char p[PATH_MAX];
    char buf[32];
    int len;
    time_t now;

    if (path_state(p, sizeof(p), "clock") != 0)
        return fail("path too long");
    if (file_exists(p))
        return 0;

    now = time(NULL);
    if (now == (time_t)-1)
        return fail("cannot read the clock");
    len = snprintf(buf, sizeof(buf), "%lld\n", (long long)now);
    if (len < 0 || (size_t)len >= sizeof(buf))
        return fail("cannot format clock");
    if (write_file(p, buf, (size_t)len) != 0)
        return fail("cannot write state/clock: %s", strerror(errno));
    return 0;
}

/* Elapsed seconds since the clock started; -1 if not started yet. */
static long elapsed_seconds(void)
{
    char p[PATH_MAX];
    char *end;
    long long started;
    time_t now;

    if (path_state(p, sizeof(p), "clock") != 0)
        return -1;
    if (read_file_bounded(p, g_aux, sizeof(g_aux), NULL) != 0)
        return -1;
    trim_ws(g_aux);
    errno = 0;
    started = strtoll(g_aux, &end, 10);
    if (errno != 0 || end == g_aux)
        return -1;
    now = time(NULL);
    if (now == (time_t)-1)
        return -1;
    if ((long long)now < started)
        return 0;
    return (long)((long long)now - started);
}

/* Load state/stage_NN.done (check ids). Empty list if absent. */
static int load_done(int n)
{
    char p[PATH_MAX];

    g_aux[0] = '\0';
    if (path_state_stage(p, sizeof(p), n, "done") != 0)
        return fail("path too long");
    if (!file_exists(p))
        return 0;
    if (read_file_bounded(p, g_aux, sizeof(g_aux), NULL) != 0)
        return fail("cannot read state/stage_%02d.done", n);
    return 0;
}

/* ------------------------------------------------------------------ */
/* manifest + checks parsing                                           */
/* ------------------------------------------------------------------ */

static int load_manifest(void)
{
    char p[PATH_MAX];
    char *buf, *p2, *save;
    int declared = -1;
    int rc_r;

    buf = malloc(MANIFEST_CAP);
    if (buf == NULL)
        return fail("out of memory");

    if (spath(p, sizeof(p), "%s/manifest", g_root) != 0) {
        free(buf);
        return fail("path too long");
    }
    rc_r = read_file_bounded(p, buf, MANIFEST_CAP, NULL);
    if (rc_r != 0) {
        free(buf);
        return fail("manifest %s", read_err(rc_r));
    }

    for (p2 = strtok_r(buf, "\n", &save); p2; p2 = strtok_r(NULL, "\n", &save)) {
        trim_ws(p2);
        if (p2[0] == '\0')
            continue;
        if (strncmp(p2, "SEED ", 5) == 0) {
            char *end;
            long v;
            errno = 0;
            v = strtol(p2 + 5, &end, 10);
            if (errno != 0 || end == p2 + 5) {
                free(buf);
                return fail("manifest: malformed SEED line");
            }
            g_seed = v;
        } else if (strncmp(p2, "STAGES ", 7) == 0) {
            char *end;
            long v;
            errno = 0;
            v = strtol(p2 + 7, &end, 10);
            if (errno != 0 || end == p2 + 7 || v < 1 || v > MAX_STAGES) {
                free(buf);
                return fail("manifest: malformed STAGES line");
            }
            declared = (int)v;
        } else if (strncmp(p2, "STAGE ", 6) == 0) {
            char *id = p2 + 6;
            trim_ws(id);
            if (!valid_id(id, ID_MAX)) {
                free(buf);
                return fail("manifest: invalid stage id '%s'", id);
            }
            if (g_nstage >= MAX_STAGES) {
                free(buf);
                return fail("manifest: too many stages");
            }
            snprintf(g_stage[g_nstage].id, ID_MAX, "%s", id);
            g_nstage++;
        } else {
            free(buf);
            return fail("manifest: unexpected line '%s'", p2);
        }
    }
    free(buf);

    if (declared < 0)
        return fail("manifest: missing STAGES line");
    if (declared != g_nstage)
        return fail("manifest: STAGES says %d but %d STAGE lines found", declared, g_nstage);
    return 0;
}

/* Find a check by id in the currently loaded stage; -1 if absent. */
static int find_check(const char *id)
{
    int i;

    for (i = 0; i < g_nchk; i++) {
        if (strcmp(g_chk[i].id, id) == 0)
            return i;
    }
    return -1;
}

/* Strip trailing whitespace in place (leading whitespace is significant). */
static void trim_right(char *s)
{
    size_t len = strlen(s);

    while (len > 0 && isspace((unsigned char)s[len - 1]))
        s[--len] = '\0';
}

/* Load and validate stages/NN/checks.tsv into g_chk[]. */
static int load_checks(int n)
{
    char p[PATH_MAX];
    char *line, *eq;
    struct check_ent cur;
    int have = 0;
    int rc_r;

    g_nchk = 0;
    memset(&cur, 0, sizeof(cur));

    if (path_stage(p, sizeof(p), n, "checks.tsv") != 0)
        return fail("path too long");
    rc_r = read_file_bounded(p, g_checks_buf, sizeof(g_checks_buf), NULL);
    if (rc_r != 0)
        return fail("stages/%02d/checks.tsv %s", n, read_err(rc_r));

    line = g_checks_buf;
    for (;;) {
        char *nl = strchr(line, '\n');
        char *next = NULL;

        if (nl != NULL) {
            *nl = '\0';
            next = nl + 1;
        }
        trim_right(line);

        if (line[0] == '#' || line[0] == '\0') {
            /* Blank line closes a block; '#' lines are comments. */
            if (line[0] == '\0' && have) {
                if (!valid_id(cur.id, ID_MAX))
                    return fail("stages/%02d/checks.tsv: block with bad or missing id", n);
                if (cur.type == CT_HASH) {
                    if (!valid_hex64(cur.answer))
                        return fail("stage %d check '%s': type=hash needs answer=<sha256>", n, cur.id);
                } else if (cur.type == CT_FILE) {
                    if (cur.path[0] != '/')
                        return fail("stage %d check '%s': type=file needs an absolute path", n, cur.id);
                    if (!valid_hex64(cur.sha))
                        return fail("stage %d check '%s': type=file needs sha256=<sha256>", n, cur.id);
                } else {
                    return fail("stage %d check '%s': type must be 'hash' or 'file'", n, cur.id);
                }
                if (cur.fragment[0] == '\0')
                    return fail("stage %d check '%s': missing fragment=", n, cur.id);
                if (find_check(cur.id) >= 0)
                    return fail("stage %d: duplicate check id '%s'", n, cur.id);
                if (g_nchk >= MAX_CHECKS)
                    return fail("stage %d: too many checks", n);
                g_chk[g_nchk++] = cur;
                have = 0;
                memset(&cur, 0, sizeof(cur));
            }
        } else {
            eq = strchr(line, '=');
            if (eq == NULL)
                return fail("stages/%02d/checks.tsv: line without '=' near '%s'", n, line);
            *eq = '\0';
            trim_ws(line);   /* key: whitespace-insensitive */
            trim_right(eq + 1); /* value: keep leading whitespace, drop trailing */

            if (strcmp(line, "id") == 0) {
                snprintf(cur.id, sizeof(cur.id), "%s", eq + 1);
                have = 1;
            } else if (strcmp(line, "type") == 0) {
                if (strcmp(eq + 1, "hash") == 0)
                    cur.type = CT_HASH;
                else if (strcmp(eq + 1, "file") == 0)
                    cur.type = CT_FILE;
                else
                    cur.type = CT_NONE;
                have = 1;
            } else if (strcmp(line, "answer") == 0) {
                snprintf(cur.answer, sizeof(cur.answer), "%s", eq + 1);
                have = 1;
            } else if (strcmp(line, "path") == 0) {
                snprintf(cur.path, sizeof(cur.path), "%s", eq + 1);
                have = 1;
            } else if (strcmp(line, "sha256") == 0) {
                snprintf(cur.sha, sizeof(cur.sha), "%s", eq + 1);
                have = 1;
            } else if (strcmp(line, "fragment") == 0) {
                snprintf(cur.fragment, sizeof(cur.fragment), "%s", eq + 1);
                have = 1;
            } else if (strcmp(line, "hint") == 0) {
                snprintf(cur.hint, sizeof(cur.hint), "%s", eq + 1);
                have = 1;
            } else {
                return fail("stages/%02d/checks.tsv: unknown key '%s'", n, line);
            }
        }

        if (next == NULL)
            break;
        line = next;
    }

    /* A final block need not be followed by a blank line. */
    if (have) {
        if (!valid_id(cur.id, ID_MAX))
            return fail("stages/%02d/checks.tsv: trailing block with bad or missing id", n);
        if (cur.type == CT_HASH && !valid_hex64(cur.answer))
            return fail("stage %d check '%s': type=hash needs answer=<sha256>", n, cur.id);
        if (cur.type == CT_FILE && (cur.path[0] != '/' || !valid_hex64(cur.sha)))
            return fail("stage %d check '%s': type=file needs absolute path + sha256", n, cur.id);
        if (cur.type == CT_NONE)
            return fail("stage %d check '%s': type must be 'hash' or 'file'", n, cur.id);
        if (cur.fragment[0] == '\0')
            return fail("stage %d check '%s': missing fragment=", n, cur.id);
        if (find_check(cur.id) >= 0)
            return fail("stage %d: duplicate check id '%s'", n, cur.id);
        if (g_nchk >= MAX_CHECKS)
            return fail("stage %d: too many checks", n);
        g_chk[g_nchk++] = cur;
    }

    if (g_nchk == 0)
        return fail("stage %d: no checks defined", n);
    return 0;
}

/* Read an optional text file; missing is not an error. */
static int load_optional_text(const char *path, char *buf, size_t cap)
{
    buf[0] = '\0';
    if (!file_exists(path))
        return 0;
    if (read_file_bounded(path, buf, cap, NULL) != 0)
        return -1;
    return 0;
}

/* Read a required <64 hex> digest file. */
static int load_digest(const char *path, char out[65])
{
    if (read_file_bounded(path, g_aux, sizeof(g_aux), NULL) != 0)
        return -1;
    trim_ws(g_aux);
    if (!valid_hex64(g_aux))
        return -1;
    memcpy(out, g_aux, 65); /* exactly 64 hex chars + NUL */
    return 0;
}

/* ------------------------------------------------------------------ */
/* commands                                                            */
/* ------------------------------------------------------------------ */

static int print_stage(int n)
{
    char p[PATH_MAX];
    int i;
    int rc_r;

    if (n < 1 || n > g_nstage)
        return fail("stage %d is out of range", n);

    /* Validate the stage's checks first: never show half a brief. */
    if (load_checks(n) != 0)
        return 1;

    if (path_stage(p, sizeof(p), n, "instruction") != 0)
        return fail("path too long");
    rc_r = read_file_bounded(p, g_text, sizeof(g_text), NULL);
    if (rc_r != 0)
        return fail("stages/%02d/instruction %s", n, read_err(rc_r));

    printf("=== Stage %d/%d: %s ===\n", n, g_nstage, g_stage[n - 1].id);
    print_text(g_text);
    printf("\n");

    printf("Checks in this stage (%d): ", g_nchk);
    for (i = 0; i < g_nchk; i++)
        printf("%s%s", i ? ", " : "", g_chk[i].id);
    printf("\n");
    printf("Submit an answer with: verify check <check-id> <answer>\n");
    printf("Need a nudge? verify hint | When every check passes: verify stage\n");
    return 0;
}

static int cmd_next(void)
{
    int cur = current_stage();

    if (cur == 0)
        return 1;

    if (cur > g_nstage) {
        long el = elapsed_seconds();
        char fmt[64];

        printf("=== All %d stages complete ===\n", g_nstage);
        if (el >= 0) {
            fmt_elapsed(el, fmt, sizeof(fmt));
            printf("Time so far: %s\n", fmt);
        }
        printf("\nRun: verify finish <final-flag>\n");
        return 0;
    }

    if (ensure_state_dir() != 0)
        return 1;
    if (ensure_clock() != 0)
        return 1;
    return print_stage(cur);
}

static int cmd_check(int argc, char **argv)
{
    const char *id;
    const char *answer;
    char expected[65], got[65];
    char p[PATH_MAX];
    char line[FRAG_MAX + ID_MAX + 8];
    int cur, idx, len, done_ct;

    if (argc != 4)
        return fail("usage: verify check <check-id> <answer>");
    id = argv[2];
    answer = argv[3];
    if (!valid_id(id, ID_MAX))
        return fail("invalid check id (allowed: A-Z a-z 0-9 _ -)");

    cur = current_stage();
    if (cur == 0)
        return 1;
    if (cur > g_nstage)
        return fail("all stages are already complete");

    if (load_checks(cur) != 0)
        return 1;

    idx = find_check(id);
    if (idx < 0)
        return fail("no check '%s' in the current stage", id);

    if (load_done(cur) != 0)
        return 1;
    if (list_has(g_aux, id))
        return fail("check '%s' is already completed", id);

    if (g_chk[idx].type == CT_FILE) {
        /* Root-only paths: keep euid 0 for this read. */
        if (sha256_file_hex(g_chk[idx].path, got) != 0)
            return fail("check '%s': cannot read the target file at all", id);
        snprintf(expected, sizeof(expected), "%s", g_chk[idx].sha);
    } else {
        /* Hostile argv data: hash it with privileges dropped. */
        if (priv_enter_user() != 0)
            return fail("cannot drop privileges for answer hashing");
        sha256_hex(answer, strlen(answer), got);
        if (priv_leave_user() != 0)
            return fail("cannot reacquire privileges");
        snprintf(expected, sizeof(expected), "%s", g_chk[idx].answer);
    }

    if (strcasecmp(got, expected) != 0) {
        printf("NOT OK: that answer does not match check '%s'.\n", id);
        printf("Re-read the instruction, or try: verify hint\n");
        return 1;
    }

    /* Success: record the fragment and mark the check done. */
    if (path_state_stage(p, sizeof(p), cur, "frag") != 0)
        return fail("path too long");
    len = snprintf(line, sizeof(line), "%s\n", g_chk[idx].fragment);
    if (len < 0 || (size_t)len >= sizeof(line))
        return fail("fragment for '%s' is too long", id);
    if (append_file(p, line, (size_t)len) != 0)
        return fail("cannot append to state/stage_%02d.frag: %s", cur, strerror(errno));

    if (path_state_stage(p, sizeof(p), cur, "done") != 0)
        return fail("path too long");
    len = snprintf(line, sizeof(line), "%s\n", id);
    if (len < 0 || (size_t)len >= sizeof(line))
        return fail("check id is too long");
    if (append_file(p, line, (size_t)len) != 0)
        return fail("cannot append to state/stage_%02d.done: %s", cur, strerror(errno));

    printf("OK  (%s): %s\n", id, g_chk[idx].fragment);

    if (load_done(cur) != 0)
        return 1;
    done_ct = count_lines(g_aux);
    printf("Progress: %d/%d checks done in stage %d.\n", done_ct, g_nchk, cur);
    if (done_ct >= g_nchk)
        printf("All checks passed - run: verify stage\n");
    else
        printf("%d check(s) left. Run: verify next for the brief.\n", g_nchk - done_ct);
    return 0;
}

/*
 * Build the "|"-joined fragment string for stage `n` in the requested order.
 * order_tsv != 0 -> checks.tsv order; else completion (append) order.
 */
static int build_join(int n, int order_tsv, char *out, size_t cap)
{
    char p[PATH_MAX];
    static char frag[FRAG_CAP];
    static char used[MAX_CHECKS * 4];
    size_t used_len = 0, off = 0;
    int i, w;

    if (path_state_stage(p, sizeof(p), n, "frag") != 0)
        return -1;
    if (!file_exists(p))
        return -1;
    if (read_file_bounded(p, frag, sizeof(frag), NULL) != 0)
        return -1;

    memset(used, 0, sizeof(used));

    /* Split the fragment file into lines we can index. */
    {
        static const char *fragline[MAX_CHECKS * 4];
        int nfrag = 0;
        char *q = frag;

        while (*q && nfrag < (int)(sizeof(fragline) / sizeof(fragline[0]))) {
            char *nl = strchr(q, '\n');
            if (nl != NULL)
                *nl = '\0';
            if (*q != '\0')
                fragline[nfrag++] = q;
            if (nl == NULL)
                break;
            q = nl + 1;
        }

        if (order_tsv) {
            /* Match each check's fragment to a stored line (first unused one). */
            for (i = 0; i < g_nchk; i++) {
                for (w = 0; w < nfrag; w++) {
                    if (!used[w] && strcmp(fragline[w], g_chk[i].fragment) == 0) {
                        used[w] = 1;
                        if (used_len > 0 && off + 1 < cap)
                            out[off++] = '|';
                        else if (used_len > 0)
                            return -1;
                        size_t l = strlen(g_chk[i].fragment);
                        if (off + l >= cap)
                            return -1;
                        memcpy(out + off, g_chk[i].fragment, l);
                        off += l;
                        used_len++;
                        break;
                    }
                }
            }
            /* Anything left over (unknown fragment) appended verbatim so the
             * failure is visible rather than silently dropped. */
            for (w = 0; w < nfrag; w++) {
                if (used[w])
                    continue;
                size_t l = strlen(fragline[w]);
                if (off > 0) {
                    if (off + 1 >= cap)
                        return -1;
                    out[off++] = '|';
                }
                if (off + l >= cap)
                    return -1;
                memcpy(out + off, fragline[w], l);
                off += l;
            }
        } else {
            for (w = 0; w < nfrag; w++) {
                size_t l = strlen(fragline[w]);
                if (w > 0) {
                    if (off + 1 >= cap)
                        return -1;
                    out[off++] = '|';
                }
                if (off + l >= cap)
                    return -1;
                memcpy(out + off, fragline[w], l);
                off += l;
            }
        }
    }

    out[off] = '\0';
    return 0;
}

static void make_flag(const char *joined, char out[32])
{
    char hex[65];

    sha256_hex(joined, strlen(joined), hex);
    snprintf(out, 32, "FLAG{%.12s}", hex);
}

static int cmd_stage(void)
{
    char p[PATH_MAX];
    char stored[65];
    static char join_tsv[JOIN_CAP];
    static char join_app[JOIN_CAP];
    char flag_tsv[32], flag_app[32];
    char flag_sha[65];
    int cur, nfrag, ndone, have_stored = 0, i;

    cur = current_stage();
    if (cur == 0)
        return 1;
    if (cur > g_nstage)
        return fail("all stages are already complete");

    if (load_checks(cur) != 0)
        return 1;

    if (path_state_stage(p, sizeof(p), cur, "frag") != 0)
        return fail("path too long");
    if (file_exists(p)) {
        if (read_file_bounded(p, g_aux, sizeof(g_aux), NULL) != 0)
            return fail("cannot read state/stage_%02d.frag", cur);
        nfrag = count_lines(g_aux);
    } else {
        nfrag = 0;
    }

    if (load_done(cur) != 0)
        return 1;
    ndone = count_lines(g_aux);

    if (nfrag != ndone)
        return fail("inconsistent state: %d fragments but %d completed checks", nfrag, ndone);

    if (nfrag < g_nchk) {
        printf("Stage %d is not finished: %d/%d checks passed.\n", cur, nfrag, g_nchk);
        printf("Remaining check ids: ");
        for (i = 0; i < g_nchk; i++) {
            if (!list_has(g_aux, g_chk[i].id))
                printf("%s ", g_chk[i].id);
        }
        printf("\n");
        if (ndone == 0)
            printf("Start with: verify next\n");
        return 1;
    }

    if (build_join(cur, 1, join_tsv, sizeof(join_tsv)) != 0)
        return fail("cannot assemble fragments for stage %d", cur);
    if (build_join(cur, 0, join_app, sizeof(join_app)) != 0)
        return fail("cannot assemble fragments for stage %d", cur);
    make_flag(join_tsv, flag_tsv);
    make_flag(join_app, flag_app);

    /* Prefer whichever ordering the trainer's stored hash agrees with. */
    if (path_stage(p, sizeof(p), cur, "flag.sha256") == 0 &&
        load_digest(p, stored) == 0) {
        have_stored = 1;
    }

    if (have_stored) {
        sha256_hex(flag_tsv, strlen(flag_tsv), flag_sha);
        if (strcasecmp(flag_sha, stored) == 0) {
            printf("Stage %d flag: %s\n", cur, flag_tsv);
            printf("Unlock it with: verify unlock %s\n", flag_tsv);
            return 0;
        }
        sha256_hex(flag_app, strlen(flag_app), flag_sha);
        if (strcasecmp(flag_sha, stored) == 0) {
            printf("Stage %d flag: %s\n", cur, flag_app);
            printf("Unlock it with: verify unlock %s\n", flag_app);
            return 0;
        }
        return fail("computed flag does not match stages/%02d/flag.sha256 "
                    "(state is inconsistent; ask the trainer, do not guess)", cur);
    }

    printf("Stage %d flag: %s\n", cur, flag_tsv);
    printf("(no flag.sha256 found; showing the checks-order flag)\n");
    return 0;
}

static int cmd_unlock(const char *flag)
{
    char p[PATH_MAX];
    char stored[65], got[65];
    char fmt[64];
    int cur, rc;

    cur = current_stage();
    if (cur == 0)
        return 1;
    if (cur > g_nstage)
        return fail("all stages are already unlocked; run: verify finish <final-flag>");
    if (flag == NULL || flag[0] == '\0')
        return fail("usage: verify unlock <flag>");

    if (path_stage(p, sizeof(p), cur, "flag.sha256") != 0)
        return fail("path too long");
    if (load_digest(p, stored) != 0)
        return fail("cannot read stages/%02d/flag.sha256", cur);

    if (priv_enter_user() != 0)
        return fail("cannot drop privileges for flag hashing");
    sha256_hex(flag, strlen(flag), got);
    if (priv_leave_user() != 0)
        return fail("cannot reacquire privileges");

    if (strcasecmp(got, stored) != 0) {
        printf("NOT OK: that flag does not unlock stage %d.\n", cur);
        printf("Run: verify stage   (earns the flag from a completed stage)\n");
        return 1;
    }

    if (write_progress(cur + 1) != 0)
        return 1;

    /* Clear the finished stage's working files. */
    if (path_state_stage(p, sizeof(p), cur, "frag") == 0 && unlink(p) != 0 && errno != ENOENT)
        return fail("unlocked, but could not clear state/stage_%02d.frag", cur);
    if (path_state_stage(p, sizeof(p), cur, "done") == 0 && unlink(p) != 0 && errno != ENOENT)
        return fail("unlocked, but could not clear state/stage_%02d.done", cur);

    printf("Stage %d (%s) unlocked.\n\n", cur, g_stage[cur - 1].id);

    if (cur < g_nstage) {
        rc = print_stage(cur + 1);
        if (rc != 0)
            return rc;
        return 0;
    }

    fmt_elapsed(elapsed_seconds(), fmt, sizeof(fmt));
    printf("=== That was the last stage - everything is unlocked ===\n");
    printf("Elapsed: %s\n", fmt);
    printf("Collect the final flag and run: verify finish <final-flag>\n");
    return 0;
}

static int cmd_finish(const char *flag)
{
    char p[PATH_MAX];
    char stored[65], got[65];
    char fmt[64];
    char json[4096];
    int cur, len, i;
    long long epoch;
    long el;

    cur = current_stage();
    if (cur == 0)
        return 1;
    if (cur <= g_nstage)
        return fail("not all stages are unlocked (stage %d/%d)", cur, g_nstage);
    if (flag == NULL || flag[0] == '\0')
        return fail("usage: verify finish <final-flag>");

    if (spath(p, sizeof(p), "%s/final.sha256", g_root) != 0)
        return fail("path too long");
    if (load_digest(p, stored) != 0)
        return fail("cannot read final.sha256");

    if (priv_enter_user() != 0)
        return fail("cannot drop privileges for flag hashing");
    sha256_hex(flag, strlen(flag), got);
    if (priv_leave_user() != 0)
        return fail("cannot reacquire privileges");

    if (strcasecmp(got, stored) != 0) {
        printf("NOT OK: that is not the final flag.\n");
        return 1;
    }

    if (path_state(p, sizeof(p), "finished") != 0)
        return fail("path too long");
    if (file_exists(p)) {
        printf("NOT OK: this run is already recorded in state/records.jsonl.\n");
        printf("Run: verify reset   to start a fresh attempt.\n");
        return 1;
    }

    el = elapsed_seconds();
    if (el < 0)
        el = 0;
    fmt_elapsed(el, fmt, sizeof(fmt));
    epoch = (long long)time(NULL);

    printf("=== Finished ===\n");
    printf("Seed:    %ld\n", g_seed);
    printf("Stages:  %d\n", g_nstage);
    printf("Elapsed: %s (%ld seconds)\n", fmt, el);
    printf("Recorded in state/records.jsonl\n");

    len = snprintf(json, sizeof(json),
                   "{\"epoch\":%lld,\"elapsed_seconds\":%ld,\"seed\":%ld,\"stages\":[",
                   epoch, el, g_seed);
    if (len < 0 || (size_t)len >= sizeof(json))
        return fail("cannot format record");
    for (i = 0; i < g_nstage; i++) {
        int r = snprintf(json + len, sizeof(json) - (size_t)len, "%s\"%s\"",
                         i ? "," : "", g_stage[i].id);
        if (r < 0 || (size_t)r >= sizeof(json) - (size_t)len)
            return fail("cannot format record");
        len += r;
    }
    {
        int r = snprintf(json + len, sizeof(json) - (size_t)len, "]}\n");
        if (r < 0 || (size_t)r >= sizeof(json) - (size_t)len)
            return fail("cannot format record");
        len += r;
    }

    if (path_state(p, sizeof(p), "records.jsonl") != 0)
        return fail("path too long");
    if (append_file(p, json, (size_t)len) != 0)
        return fail("cannot append to state/records.jsonl: %s", strerror(errno));

    /* Marker so a second `verify finish` cannot append a duplicate record. */
    {
        char mark[64];
        int n;
        if (path_state(p, sizeof(p), "finished") != 0)
            return fail("path too long");
        n = snprintf(mark, sizeof(mark), "epoch=%lld\n", epoch);
        if (n < 0 || (size_t)n >= sizeof(mark))
            return fail("cannot format finished marker");
        if (write_file(p, mark, (size_t)n) != 0)
            return fail("cannot write state/finished: %s", strerror(errno));
    }
    return 0;
}

static int cmd_hint(int argc, char **argv)
{
    static char hints[MAX_CHECKS + 40][HINT_MAX];
    char p[PATH_MAX];
    int nhints = 0, want = 1, i;
    char *q;

    int cur = current_stage();
    if (cur == 0)
        return 1;
    if (cur > g_nstage)
        return fail("all stages are complete; run: verify finish <final-flag>");

    if (argc > 3)
        return fail("usage: verify hint [n]");
    if (argc == 3) {
        char *end;
        long v;
        errno = 0;
        v = strtol(argv[2], &end, 10);
        if (errno != 0 || end == argv[2] || *end != '\0' || v < 1)
            return fail("hint number must be a positive integer");
        want = (int)v;
    }

    /* Hints come from stages/NN/hint (free text lines) first, then any
     * per-check hint= fields, in checks.tsv order. Answers are never shown. */
    if (path_stage(p, sizeof(p), cur, "hint") != 0)
        return fail("path too long");
    if (load_optional_text(p, g_text, sizeof(g_text)) != 0)
        return fail("cannot read stages/%02d/hint", cur);

    q = g_text;
    while (*q && nhints < (int)(sizeof(hints) / sizeof(hints[0]))) {
        char *nl = strchr(q, '\n');
        char *home;
        if (nl != NULL)
            *nl = '\0';
        trim_right(q);
        home = q;
        while (*home && isspace((unsigned char)*home))
            home++;
        if (*home != '\0') {
            snprintf(hints[nhints], HINT_MAX, "%s", home);
            nhints++;
        }
        if (nl == NULL)
            break;
        q = nl + 1;
    }

    if (load_checks(cur) != 0)
        return 1;
    for (i = 0; i < g_nchk && nhints < (int)(sizeof(hints) / sizeof(hints[0])); i++) {
        if (g_chk[i].hint[0] != '\0') {
            snprintf(hints[nhints], HINT_MAX, "%s", g_chk[i].hint);
            nhints++;
        }
    }

    if (nhints == 0) {
        printf("No hints for stage %d. Re-read the instruction: verify next\n", cur);
        return 0;
    }
    if (want > nhints) {
        printf("Stage %d has %d hint(s); showing all of them.\n", cur, nhints);
        want = nhints;
    }

    for (i = 0; i < want; i++)
        printf("Hint %d/%d: %s\n", i + 1, nhints, hints[i]);
    if (want < nhints)
        printf("(%d more: verify hint %d)\n", nhints - want, want + 1);
    return 0;
}

static int cmd_status(void)
{
    char fmt[64];
    long el;
    int cur, ndone = 0;

    cur = current_stage();
    if (cur == 0)
        return 1;

    printf("Seed:  %ld\n", g_seed);
    printf("Stages: %d\n", g_nstage);

    if (cur > g_nstage) {
        el = elapsed_seconds();
        printf("Stage: all %d complete\n", g_nstage);
        if (el >= 0) {
            fmt_elapsed(el, fmt, sizeof(fmt));
            printf("Elapsed: %s\n", fmt);
        }
        printf("Next:  verify finish <final-flag>\n");
        return 0;
    }

    printf("Stage: %d/%d (%s)\n", cur, g_nstage, g_stage[cur - 1].id);

    el = elapsed_seconds();
    if (el >= 0) {
        fmt_elapsed(el, fmt, sizeof(fmt));
        printf("Elapsed: %s\n", fmt);
    } else {
        printf("Elapsed: not started (run: verify next)\n");
    }

    if (load_checks(cur) == 0 && load_done(cur) == 0)
        ndone = count_lines(g_aux);
    printf("Checks: %d/%d done in this stage\n", ndone, g_nchk);
    return 0;
}

static int cmd_reset(void)
{
    char p[PATH_MAX];
    int i, removed = 0;

    if (path_state(p, sizeof(p), "clock") == 0 && unlink(p) == 0)
        removed++;
    if (path_state(p, sizeof(p), "progress") == 0 && unlink(p) == 0)
        removed++;
    if (path_state(p, sizeof(p), "finished") == 0 && unlink(p) == 0)
        removed++;
    for (i = 1; i <= g_nstage; i++) {
        if (path_state_stage(p, sizeof(p), i, "frag") == 0 && unlink(p) == 0)
            removed++;
        if (path_state_stage(p, sizeof(p), i, "done") == 0 && unlink(p) == 0)
            removed++;
    }

    if (ensure_state_dir() != 0)
        return 1;
    if (write_progress(1) != 0)
        return 1;

    printf("Progress reset (%d state file(s) cleared). Back at stage 1.\n", removed);
    printf("Files, answers and the completion log were left untouched.\n");
    return 0;
}

static void usage(FILE *out)
{
    fputs("usage: verify <command> [args]\n"
          "\n"
          "  next                      show the current stage brief\n"
          "  check <check-id> <answer> test one answer for the current stage\n"
          "  stage                     earn this stage's flag once all checks pass\n"
          "  unlock <flag>             unlock the next stage with a stage flag\n"
          "  finish <final-flag>       record completion after the last stage\n"
          "  hint [n]                  print hint n (default 1) for this stage\n"
          "  status                    where you are, elapsed time, progress\n"
          "  reset                     clear your progress (not the challenge)\n",
          out);
}

int main(int argc, char **argv)
{
    int rc;

    umask(0077);

    /* Capture the setuid state before anything can change it, and normalise
     * the effective gid so state files land as root:root. */
    g_setuid_root = (geteuid() == 0 && getuid() != 0);
    if (g_setuid_root)
        (void)setegid(0);

    if (init_root() != 0)
        return 1;

    if (argc < 2) {
        usage(stderr);
        return 2;
    }

    if (strcmp(argv[1], "--help") == 0 || strcmp(argv[1], "-h") == 0 ||
        strcmp(argv[1], "help") == 0) {
        usage(stdout);
        return 0;
    }

    if (load_manifest() != 0)
        return 1;

    if (strcmp(argv[1], "next") == 0) {
        rc = cmd_next();
    } else if (strcmp(argv[1], "check") == 0) {
        rc = cmd_check(argc, argv);
    } else if (strcmp(argv[1], "stage") == 0) {
        rc = cmd_stage();
    } else if (strcmp(argv[1], "unlock") == 0) {
        rc = (argc == 3) ? cmd_unlock(argv[2]) : fail("usage: verify unlock <flag>");
    } else if (strcmp(argv[1], "finish") == 0) {
        rc = (argc == 3) ? cmd_finish(argv[2]) : fail("usage: verify finish <final-flag>");
    } else if (strcmp(argv[1], "hint") == 0) {
        rc = cmd_hint(argc, argv);
    } else if (strcmp(argv[1], "status") == 0) {
        rc = cmd_status();
    } else if (strcmp(argv[1], "reset") == 0) {
        rc = cmd_reset();
    } else {
        fail("unknown command '%s'", argv[1]);
        usage(stderr);
        rc = 2;
    }

    fflush(stdout);
    return rc;
}
